// @story:SCRUM-21
// @ac:1
// @design:D10
// @type:functional
// @technique:state-transition
test("AC-1 – A signed-in customer can submit a review and a confirmation is shown", async ({ page }) => {
  const baseURL = process.env["AQA_APP_URL"] || "http://localhost:3100";

  // Precondition: sign in via API and confirm authentication succeeded
  const apiContext = await playwrightRequest.newContext({ baseURL });
  const loginResp = await apiContext.post("/rest/user/login", {
    data: { email: process.env["AQA_APP_USER"], password: process.env["AQA_APP_PASS"] },
  });
  expect(loginResp.status(), "Precondition: login must succeed (200) — check AQA_APP_USER / AQA_APP_PASS").toBe(200);
  const loginBody = await loginResp.json();
  const token = loginBody?.authentication?.token;
  expect(token, "Precondition: authentication token must be present in login response").toBeTruthy();
  await apiContext.dispose();

  // Authenticate the browser session
  await page.goto("/#/");
  await page.evaluate((t) => { localStorage.setItem("token", t); }, token);
  await page.goto("/#/");

  // Dismiss cookie banner if present
  const cookieBtn = page.getByRole("button", { name: "Me want it!" });
  if (await cookieBtn.isVisible()) await cookieBtn.click();

  // Wait for products to load and open Apple Juice detail dialog
  const productCard = page.locator("mat-grid-tile").filter({ hasText: "Apple Juice (1000ml)" }).first();
  await expect(productCard).toBeVisible();
  await productCard.getByRole("button", { name: /more information/i }).click();

  // Wait for the product detail dialog to open
  const dialog = page.locator("mat-dialog-container");
  await expect(dialog).toBeVisible();

  // Locate the review text area and enter review text
  const reviewTextArea = dialog.locator("textarea").first();
  await expect(reviewTextArea, "Precondition: review text area must be visible in the product detail dialog").toBeVisible();
  await reviewTextArea.fill("Great product, highly recommended!");

  // Click the Submit button
  const submitBtn = dialog.getByRole("button", { name: /submit/i });
  await expect(submitBtn).toBeEnabled();
  await submitBtn.click();

  // Assert: confirmation message is shown (state after action)
  await expect(page.getByText(/thank you for your review|review was submitted/i).first()).toBeVisible();
});

// @story:SCRUM-21
// @ac:2
